custom_qss:
/* ============================================================
   JUMBO — oversized body type. Everything scaled way up (18px
   body) so labels overflow their buttons and the UI feels cramped
   and aggressive. One warm-orange accent on dark. Opposite of the
   small precise look.
   ============================================================ */

* { font-size: 18px; color: #f0e8dc; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget { background: transparent; border: none; }

QMainWindow { background: #100e0c !important; border: none; }
QDialog { background: #1a1714 !important; border: 1px solid #463c30; }

QMenuBar { background: #141110 !important; border: none; }
QMenuBar::item { padding: 6px 15px; background: transparent !important; color: #8a7e6e; }
QMenuBar::item:selected { background: #26211c !important; color: #ff8c42; }
QMenuBar::item:disabled { color: #544a3e; }

QMenu { background: #1a1714 !important; border: 1px solid #463c30; padding: 7px; font-size: 15px;}
QMenu::item { padding: 8px 26px 8px 14px; background: transparent !important; color: #f0e8dc; }
QMenu::item:selected { background: #ff8c42 !important; color: #100e0c; }
QMenu::item:disabled { color: #544a3e; }
QMenu::separator { height: 1px; background: #332c24; margin: 7px 10px; }

QToolBar { background: #141110 !important; border: none; spacing: 3px; padding: 5px; }
QToolBar::separator { background: #332c24; width: 1px; margin: 7px 5px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 7px 12px; border: 1px solid transparent; color: #c0b4a4; font-size: 16px;}
QToolBar QToolButton:hover, QToolButton:hover { background: #26211c !important; color: #ff8c42; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed, QToolButton:checked, QToolButton:pressed { background: #ff8c42 !important; color: #100e0c; }

QPushButton { background: #1a1714 !important; border: 1px solid #332c24; border-radius: 4px; padding: 9px 22px; color: #f0e8dc; font-weight: 600; font-size: 15px;}
QPushButton:hover { background: #26211c !important; border: 1px solid #ff8c42; color: #ff8c42; }
QPushButton:pressed { background: #ff8c42 !important; color: #100e0c; }
QPushButton:checked { background: #26211c !important; border: 1px solid #ff8c42; color: #ff8c42; }
QPushButton:default { border: 1px solid #ff8c42; }
QPushButton:disabled { background: #141110 !important; color: #544a3e; }

QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit { background: #0a0806 !important; border: 1px solid #332c24; border-radius: 3px; padding: 8px 12px; color: #ff8c42; selection-background-color: #ff8c42; selection-color: #100e0c; font-size: 15px;}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #544a3e; }

QDockWidget { background: #1a1714 !important; border: 1px solid #332c24; border-radius: 4px; }
QDockWidget::title { background: #141110 !important; border: none; border-left: 3px solid #ff8c42; border-radius: 3px; margin: 3px; padding: 8px 12px; color: #c0b4a4; font-weight: 700; }
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: 1px solid transparent; border-radius: 3px; padding: 3px; icon-size: 16px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #26211c !important; }

QGroupBox { background: transparent !important; border: 1px solid #332c24; border-radius: 4px; margin-top: 14px; padding-top: 12px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 10px; color: #ff8c42; font-weight: 700; background: #100e0c; }

QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }
QComboBox { background: #0a0806 !important; border: 1px solid #332c24; border-radius: 3px; padding: 6px 10px; color: #f0e8dc; font-size: 15px;}
QComboBox:hover { border: 1px solid #463c30; }
QComboBox:focus { border: 1px solid #ff8c42; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: #1a1714 !important; border: 1px solid #463c30; padding: 5px; selection-background-color: #ff8c42; selection-color: #100e0c; font-size: 15px;}
QCheckBox, QRadioButton { color: #f0e8dc; background: transparent !important; padding: 3px; }
QCheckBox::indicator, QRadioButton::indicator { width: 15px; height: 15px; border-radius: 2px; background: #0a0806 !important; border: 1px solid #463c30; }
QRadioButton::indicator { border-radius: 8px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 1px solid #ff8c42; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: #ff8c42 !important; border: 1px solid #ff8c42; }
QTabBar::tab { background: transparent !important; color: #8a7e6e; padding: 8px 16px; border: none; border-bottom: 2px solid transparent; }
QTabBar::tab:hover { color: #f0e8dc; }
QTabBar::tab:selected { color: #ff8c42; border-bottom: 2px solid #ff8c42; }
QTabWidget::pane { border: none; }
QAbstractItemView { background: #0a0806 !important; border: 1px solid #332c24; border-radius: 3px; outline: none; alternate-background-color: #141110; selection-background-color: #ff8c42; selection-color: #100e0c; }
QAbstractItemView::item { padding: 5px 10px; border: none; color: #f0e8dc; }
QAbstractItemView::item:hover { background: #26211c !important; color: #ff8c42; }
QAbstractItemView::item:selected { background: #ff8c42 !important; color: #100e0c !important; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #141110 !important; border: none; border-bottom: 1px solid #463c30; padding: 6px 10px; color: #c0b4a4; font-weight: 700; }
QScrollBar:vertical { background: #0a0806; width: 10px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: #463c30; border-radius: 2px; min-height: 30px; }
QScrollBar::handle:vertical:hover { background: #ff8c42; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: #0a0806; height: 10px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: #463c30; border-radius: 2px; min-width: 30px; }
QScrollBar::handle:horizontal:hover { background: #ff8c42; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }
QSlider::groove:horizontal { background: #0a0806; border: 1px solid #332c24; height: 6px; border-radius: 3px; }
QSlider::sub-page:horizontal { background: #ff8c42; border-radius: 3px; }
QSlider::add-page:horizontal { background: #0a0806; border-radius: 3px; }
QSlider::handle:horizontal { background: #ff8c42; width: 13px; height: 15px; margin: -5px 0; border: 2px solid #100e0c; border-radius: 8px; }
QSlider::handle:horizontal:hover { background: #ffb37a; }
QSlider::groove:vertical { background: #0a0806; border: 1px solid #332c24; width: 6px; border-radius: 3px; }
QSlider::sub-page:vertical { background: #ff8c42; border-radius: 3px; }
QSlider::handle:vertical { background: #ff8c42; width: 15px; height: 13px; margin: 0 -5px; border: 2px solid #100e0c; border-radius: 8px; }
QProgressBar { background: #0a0806; border: 1px solid #332c24; border-radius: 3px; text-align: center; color: #c0b4a4; font-size: 11px; min-height: 15px; }
QProgressBar::chunk { background: #ff8c42; border-radius: 2px; }
QStatusBar { background: #141110 !important; color: #8a7e6e; font-size: 11px; }
QStatusBar::item { border: none; }
QToolTip { background: #1a1714 !important; border: 1px solid #ff8c42; border-radius: 3px; padding: 6px 10px; color: #f0e8dc; }
QSplitter::handle { background: #332c24; }
QSplitter::handle:hover { background: #ff8c42; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #0a0806 !important; border: 1px solid #332c24; border-radius: 3px; outline: none; }
